// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait VesselStatusAssessment_Api {
  def id: Art.BridgeId
  def vessel_status_Id : Art.PortId
  def vessel_readiness_Id : Art.PortId
  def vessel_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var vessel_readiness: Docking_Access_Supervisor.VesselFacts = $

  def put_vessel_readiness(value : Docking_Access_Supervisor.VesselFacts) : Unit = {
    Contract(
      Modifies(vessel_readiness),
      Ensures(
        vessel_readiness == value
      )
    )
    Spec {
      vessel_readiness = value
    }

    Art.putValue(vessel_readiness_Id, Docking_Access_Supervisor.VesselFacts_Payload(value))
  }

  // Logika spec var representing port state for outgoing data port
  @spec var vessel_facts: Docking_Access_Supervisor.VesselFacts = $

  def put_vessel_facts(value : Docking_Access_Supervisor.VesselFacts) : Unit = {
    Contract(
      Modifies(vessel_facts),
      Ensures(
        vessel_facts == value
      )
    )
    Spec {
      vessel_facts = value
    }

    Art.putValue(vessel_facts_Id, Docking_Access_Supervisor.VesselFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class VesselStatusAssessment_Initialization_Api (
  val id: Art.BridgeId,
  val vessel_status_Id : Art.PortId,
  val vessel_readiness_Id : Art.PortId,
  val vessel_facts_Id : Art.PortId) extends VesselStatusAssessment_Api

@datatype class VesselStatusAssessment_Operational_Api (
  val id: Art.BridgeId,
  val vessel_status_Id : Art.PortId,
  val vessel_readiness_Id : Art.PortId,
  val vessel_facts_Id : Art.PortId) extends VesselStatusAssessment_Api {

  // Logika spec var representing port state for incoming data port
  @spec var vessel_status: Docking_Access_Supervisor.VesselStatus.Type = $

  def get_vessel_status() : Option[Docking_Access_Supervisor.VesselStatus.Type] = {
    Contract(
      Ensures(
        Res == Some(vessel_status)
      )
    )
    val value : Option[Docking_Access_Supervisor.VesselStatus.Type] = Art.getValue(vessel_status_Id) match {
      case Some(Docking_Access_Supervisor.VesselStatus_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port vessel_status.  Expecting 'Docking_Access_Supervisor.VesselStatus_Payload' but received ${v}")
        None[Docking_Access_Supervisor.VesselStatus.Type]()
      case _ => None[Docking_Access_Supervisor.VesselStatus.Type]()
    }
    return value
  }
}
